SELECT id, order_id, NTILE(3) OVER (PARTITION BY order_id, status ORDER BY amount DESC, id) AS amount_bucket, AVG(amount) OVER (PARTITION BY order_id ORDER BY amount, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS amount_avg_3_prior, SUM(amount) OVER (PARTITION BY status ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_amount, LAST_VALUE(amount) IGNORE NULLS OVER (PARTITION BY method, status ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_amount FROM payments
